require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';Auth::requirePermission('transactions.view');$db=Database::connect();marketplace_install($db);
if(!is_post()||!CSRF::verify()){flash('error','Token keamanan tidak valid.');legacy_redirect('admin/marketplace-service/index.php');}$id=(int)($_POST['id']??0);$case=marketplace_service_get($db,$id);if(!$case){flash('error','Pengajuan tidak ditemukan.');legacy_redirect('admin/marketplace-service/index.php');}$action=(string)($_POST['action']??'');
try{
 if($action==='reply'){$msg=trim((string)($_POST['message']??''));if($msg==='')throw new RuntimeException('Pesan tidak boleh kosong.');marketplace_service_add_message($db,$id,'admin',(int)(Auth::user()['id']??0),$msg);$db->prepare("UPDATE marketplace_service_cases SET status=CASE WHEN status IN('resolved','closed','rejected') THEN status ELSE 'waiting_customer' END,updated_at=NOW() WHERE id=?")->execute([$id]);$fresh=marketplace_service_get($db,$id);if($fresh)marketplace_service_notify_customer($db,$fresh,'Balasan admin',$msg);flash('success','Balasan dikirim.');}
 elseif($action==='update'){
   $status=(string)($_POST['status']??'waiting_admin');if(!in_array($status,['waiting_admin','waiting_customer','approved','rejected','resolved','closed'],true))$status='waiting_admin';$admin=trim((string)($_POST['admin_note']??''));$refund=(string)($_POST['refund_status']??'none');if(!in_array($refund,['none','pending','processed','rejected'],true))$refund='none';$amount=max(0,(float)($_POST['refund_amount']??0));$method=trim((string)($_POST['refund_method']??''));$ref=trim((string)($_POST['refund_reference']??''));
