   $wasRefund=(string)$case['refund_status']==='processed';$db->prepare("UPDATE marketplace_service_cases SET status=?,admin_note=?,refund_status=?,refund_amount=?,refund_method=?,refund_reference=?,refund_processed_at=CASE WHEN ?='processed' THEN COALESCE(refund_processed_at,NOW()) ELSE refund_processed_at END,resolved_at=CASE WHEN ? IN('resolved','closed') THEN COALESCE(resolved_at,NOW()) ELSE resolved_at END,updated_at=NOW() WHERE id=?")->execute([$status,$admin?:null,$refund,$amount,$method?:null,$ref?:null,$refund,$status,$id]);
   if($refund==='processed'&&!$wasRefund){marketplace_reverse_customer_points($db,(int)$case['order_id'],'Pembalikan poin karena refund');if($case['case_type']==='cancel_refund'&&!in_array($case['order_status'],['shipped','completed','cancelled','expired'],true)){$db->prepare("UPDATE online_orders SET order_status='cancelled',cancelled_at=COALESCE(cancelled_at,NOW()),updated_at=NOW() WHERE id=?")->execute([(int)$case['order_id']]);marketplace_release_stock($db,(int)$case['order_id'],'Refund pembatalan marketplace diproses.');marketplace_add_event($db,(int)$case['order_id'],'cancelled','Pembatalan & refund diproses','Referensi refund: '.$ref);}else{marketplace_add_event($db,(int)$case['order_id'],'refund','Refund diproses','Referensi refund: '.$ref);}}
   $fresh=marketplace_service_get($db,$id);if($fresh)marketplace_service_notify_customer($db,$fresh,'Status bantuan diperbarui',marketplace_service_status_label($status).($admin!==''?' • '.$admin:''));Auth::log('marketplace_service_update',$case['case_number'].' / '.$status);flash('success','Pengajuan berhasil diperbarui.');
 } else throw new RuntimeException('Aksi tidak dikenali.');
